describe('Email Address Change with Confirmation Step', () => {
  beforeEach(() => {
    cy.visit('/user/profile');
  });

  it('should successfully change email address with confirmation step', () => {
    // Verify initial email is displayed
    cy.get('[data-testid="current-email"]').should('be.visible').should('contain', 'user@example.com');

    // Intercept the API call to change email
    cy.intercept('POST', '/api/user/change-email').as('changeEmail');

    // Fill new email address
    cy.get('[data-testid="new-email-input"]').type('newuser@example.com');

    // Verify email input is valid
    cy.get('[data-testid="email-input"]').should('have.value', 'newuser@example.com');

    // Click the submit button
    cy.get('[data-testid="change-email-button"]').click();

    // Wait for API call
    cy.wait('@changeEmail').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });

    // Verify confirmation modal appears
    cy.get('[data-testid="confirmation-modal"]').should('be.visible');

    // Verify confirmation message
    cy.get('[data-testid="confirmation-message"]').should('contain', 'Email address has been changed successfully');

    // Verify old email is no longer displayed
    cy.get('[data-testid="current-email"]').should('not.exist');

    // Verify new email is displayed
    cy.get('[data-testid="new-email-input"]').should('be.visible').should('contain', 'newuser@example.com');

    // Verify success toast appears
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Email updated');
  });

  it('should display error when email validation fails', () => {
    // Verify initial email is displayed
    cy.get('[data-testid="current-email"]').should('be.visible').should('contain', 'user@example.com');

    // Fill invalid email address
    cy.get('[data-testid="new-email-input"]').type('invalid-email');

    // Verify email input is still visible
    cy.get('[data-testid="new-email-input"]').should('have.value', 'invalid-email');

    // Click the submit button
    cy.get('[data-testid="change-email-button"]').click();

    // Wait for API call
    cy.wait('@changeEmail').then((interception) => {
      expect(interception.response.statusCode).to.equal(400);
    });

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid email address');

    // Verify confirmation modal does not appear
    cy.get('[data-testid="confirmation-modal"]').should('not.exist');

    // Verify old email is still displayed
    cy.get('[data-testid="current-email"]').should('be.visible').should('contain', 'user@example.com');

    // Verify success toast does not appear
    cy.get('[data-testid="success-toast"]').should('not.exist');
  });
});
